select NICKNAME
from USERS
where USER_NO = #{userNo}

select EMAIL
from USERS
where USER_NO = #{userNo}

select PHONE_NUMBER
from USERS
where USER_NO = #{userNo}

mapper.update:
update USERS
	set PROFILE_IMG = #{profileImg}, EMAIL = #{email}, 
		NICKNAME = #{nickname},	PHONE_NUMBER = #{phoneNumber},
		REGION_ADDRESS = #{regionAddress}
where USER_NO = #{userNo}

update USERS
	set IS_DELETED = 1, DELETED_AT = sysdate
where USER_NO = #{userNo}
